// ********************** GOOGLE CLOUD STORAGE **********************

private static final String GOOGLE_BUCKET_NAME_CONFIG_KEY = "google.storage.bucket.name"
private static final String GOOGLE_CREDENTIALS_RESOURCE_CONFIG_KEY = "google.storage.credentials.resource"
private static final String DEFAULT_GOOGLE_CREDENTIALS_RESOURCE = "google-service-account.json"

private static String fetchStorageConfigValue(String configKey, String environmentVariable) {
    String value = null
    try {
        value = Holders.getFlatConfig()?.get(configKey)
    } catch (Exception e) {
        log.debug("Grails config is not available for ${configKey} ==>> ${e.message}")
    }
    if (StringUtils.isBlank(value))
        value = System.getenv(environmentVariable)
    value
}

public static String getGoogleStorageBucketName() {
    fetchStorageConfigValue(GOOGLE_BUCKET_NAME_CONFIG_KEY, "GOOGLE_STORAGE_BUCKET_NAME")
}

/**
 * Builds the Google Cloud Storage service. The deployed runtime ships its service account
 * resource on the classpath, hence it is looked up there first and the ambient(default)
 * credentials of the machine are used as a fallback.
 */
public static Storage getGoogleStorageService() {
    String credentialsResource = fetchStorageConfigValue(GOOGLE_CREDENTIALS_RESOURCE_CONFIG_KEY,
            "GOOGLE_STORAGE_CREDENTIALS_RESOURCE") ?: DEFAULT_GOOGLE_CREDENTIALS_RESOURCE
    InputStream credentialsStream = HelperMethod.getClassLoader()?.getResourceAsStream(credentialsResource)
    if (credentialsStream) {
        try {
            GoogleCredentials credentials = GoogleCredentials.fromStream(credentialsStream)
            return StorageOptions.newBuilder().setCredentials(credentials).build().getService()
        } catch (Throwable t) {
            log.error("Exception while reading Google service account resource ${credentialsResource} ==>> ${t.message}", t)
        } finally {
            credentialsStream.close()
        }
    }
    StorageOptions.getDefaultInstance().getService()
}

private static BlobId getGoogleBlobId(String path) {
    BlobId.of(getGoogleStorageBucketName(), path)
}

public static Boolean uploadObjectToGoogleCloudStorage(File file, String path) {
    Boolean isFileUploaded = Boolean.FALSE
    if (StringUtils.isNotBlank(path)) {
        try {
            Storage storage = getGoogleStorageService()
            BlobInfo blobInfo = BlobInfo.newBuilder(getGoogleBlobId(path)).build()
            storage.create(blobInfo, FileUtils.readFileToByteArray(file))
            isFileUploaded = Boolean.TRUE
        }
        catch (Exception e) {
            log.error("Exception while uploading file to Google Cloud Storage ==>> ${e.message}", e)
        }
    }
    isFileUploaded
}

public static InputStream downloadObjectFromGoogleCloudStorage(String path) {
    InputStream inputStream = null
    if (StringUtils.isNotBlank(path)) {
        try {
            byte[] content = fetchGoogleObjectContent(getGoogleStorageService(), getGoogleBlobId(path))
            if (content != null)
                inputStream = new ByteArrayInputStream(content)
        }
        catch (Exception e) {
            log.error("Exception while downloading file from Google Cloud Storage ==>> ${e.message}", e)
        }
    }
    inputStream
}

private static byte[] fetchGoogleObjectContent(Storage storage, BlobId blobId) {
    try {
        return storage.readAllBytes(blobId)
    } catch (MissingMethodException | UnsupportedOperationException e) {
        log.debug("Falling back on the blob handle to read ${blobId} ==>> ${e.message}")
        def blob = storage.get(blobId)
        return blob?.getContent()
    }
}

public static Boolean deleteObjectFromGoogleCloudStorage(String path) {
    Boolean isFileDeleted = Boolean.FALSE
    if (StringUtils.isNotBlank(path)) {
        try {
            isFileDeleted = getGoogleStorageService().delete(getGoogleBlobId(path)) as Boolean
        }
        catch (Exception e) {
            log.error("Exception while deleting file from Google Cloud Storage ==>> ${e.message}", e)
        }
    }
    isFileDeleted
}

